/** The answer of estimateAnalysis: the body of a successful estimate_analysis. */
export type EstimateAnalysisOutput = {
  estimate: {
    /** The price of a new analysis, build or preparation of this project, in credits. */
    credits: number;
    /** What the start would charge now: the price, or 0 when the same work is already running. */
    creditsToCharge: number;
    /** The length of video the price is computed on, in seconds: the source, or the main and the background video of a split screen together. 0 when the price does not depend on a video, as for a Reddit story. */
    sourceDurationSec: number;
    /** The job of the analysis or build already running on the project; null when none is. */
    runningJobId: string | null;
    /** The credits the API can spend now. On the Creator and Studio plans, what is left of the plan this month plus top-up credits, without the API bonus. On any other plan, what is left of the API bonus, or 0 when there is none. See payer and bonusRemaining. */
    creditsAvailable: number;
    /** true when the account must choose a plan in the GPT-Video app before it can spend its credits. While the API bonus is active, a call through the API spends it even when planRequired is true. It does not say whether the API may spend the plan credits: only the Creator and Studio plans can. */
    planRequired: boolean;
    /** true when the start would not be refused for credits or plan, that is when payer is not null. Always true while the same work is running, because that job is returned and nothing is charged. */
    enough: boolean;
    /** Who would pay the start now: plan is the credits of the account's plan, api_bonus is the API bonus. null when the start would be refused for credits or plan, and when the same work is already running and nothing would be charged. */
    payer: "plan" | "api_bonus" | (string & {}) | null;
    /** The credits left in the API bonus, 0 once it is used up, expired or cancelled; null when the account never had one. */
    bonusRemaining: number | null;
  };
};

