/** The input of editComposition: the fields of the edit_composition operation, with the names the API uses. */
export type EditCompositionInput = {
  /** The id of the composition: accept_clip returns it for a clip, and list_compositions or the project's compositionId give it for the other kinds of project. */
  compositionId: string;
  /** The revision of the composition you read with get_composition. If the composition changed since, the request answers CONFLICT and changes nothing. */
  expectedRevision: number;
  /** The new title of the composition, from 1 to 200 characters. */
  title?: string;
  /** Auto Clip only: the text shown over the first 2 seconds, up to 120 characters and 12 words. null removes it. */
  hook?: string | null;
  /** The captions to change. Captions added to a composition that has none are made from the transcript of its video. */
  captions?: {
    /** false removes the captions. true adds them back from the transcript when the composition has none. */
    enabled?: boolean;
    /** The caption style, as get_setting_options lists them. */
    style?: "bold-karaoke" | "word-pop" | "boxed" | "outline";
    /** The caption options to change. A field you leave out stays as it is. */
    options?: {
      /** The typeface of the captions. */
      fontFamily?: "Montserrat" | "Anton" | "System";
      /** The size of the caption text, from 20 to 200. */
      fontSize?: number;
      /** Where the captions sit, from 0 at the top to 100 at the bottom. */
      yPercent?: number;
      /** The color of the words, as #RRGGBB. */
      color?: string;
      /** The color of the word being spoken, as #RRGGBB. */
      highlightColor?: string;
      /** How many words are on screen at once, at most, from 1 to 12. */
      maxWordsPerGroup?: number;
      /** How many characters are on screen at once, at most, from 4 to 80. */
      maxCharsPerGroup?: number;
      /** true shows the captions in capital letters. */
      uppercase?: boolean;
      /** The longest pause, in seconds, inside one group of words on screen, from 0.1 to 5. */
      maxGapSec?: number;
    };
  };
  /** Auto Clip and streamer only: the start and end on the source video. A value you leave out stays as it is. */
  trim?: {
    /** The new start, in seconds of the source video. */
    startSec?: number;
    /** The new end, in seconds of the source video. */
    endSec?: number;
  };
  /** The volume of the music: 0 is muted, 1 is normal, 2 is double. */
  musicVolume?: number;
};

/** The answer of editComposition: the body of a successful edit_composition. */
export type EditCompositionOutput = {
  composition: Composition;
  /** The fields whose value is now different. Empty when the request changed nothing: then nothing was written and the revision is the one you sent. */
  changed: ("title" | "hook" | "captions" | "trim" | "musicVolume" | (string & {}))[];
  /** What else happened, or why a field changed nothing, one sentence each. */
  notes: string[];
};

/** The input of replaceCaptionWords: the fields of the replace_caption_words operation, with the names the API uses. */
export type ReplaceCaptionWordsInput = {
  /** The id of the composition: accept_clip returns it for a clip, and list_compositions or the project's compositionId give it for the other kinds of project. */
  compositionId: string;
  /** The revision of the composition you read with get_composition. If the composition changed since, the request answers CONFLICT and changes nothing. */
  expectedRevision: number;
  /** The words to replace, from 1 to 30. When two replacements find the same word, the first one wins it. */
  replacements: readonly {
    /** The word to find, compared without capitals or punctuation. */
    from: string;
    /** The text to write in its place. */
    to: string;
    /** Which occurrence of the word to replace, counting from 1. Leave it out to replace every one. */
    occurrence?: number;
  }[];
};

/** The answer of replaceCaptionWords: the body of a successful replace_caption_words. */
export type ReplaceCaptionWordsOutput = {
  composition: Composition;
  /** Every replacement that found its word, with how many words it changed. */
  replaced: {
    from: string;
    count: number;
  }[];
  /** Every replacement that found no word, with up to three similar words of the captions. */
  notFound: {
    from: string;
    similar: string[];
  }[];
};

