/**
 * Test event.
 *
 * Sent when you send a test event from the Developers page. It is never sent again and does not count when a webhook keeps failing.
 */
export type WebhookTestEvent = {
  /** The event type. */
  type: "webhook.test";
  /** When the event happened, in UTC. */
  timestamp: string;
  data: {
    /** The webhook the test was sent to. */
    endpointId: string;
  };
};

/** Every webhook event GPT-Video sends, told apart by type. An event type added after this version of the SDK arrives with a type that is not in this list: handle the types you know, and leave the others. */
export type WebhookEvent = JobCompletedEvent | JobFailedEvent | JobCancelledEvent | ExportCompletedEvent | ExportFailedEvent | ExportCancelledEvent | WebhookTestEvent;

/** The type of a webhook event: job.completed. */
export type WebhookEventType = WebhookEvent["type"];

